WITH lines AS (SELECT id, service, host, log_ts, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS attr_key, attr_value) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, ROUND(AVG(latency_ms), 2) AS avg_latency_ms, SIZE(COLLECT_SET(attr_key)) AS num_attr_keys, MAX(log_ts) AS last_seen, STDDEV_SAMP(latency_ms) AS latency_ms_stddev, SUM(status_code) FILTER (WHERE host = 'h3') AS h3_total_status_code FROM lines GROUP BY DATE_TRUNC('HOUR', log_ts) ORDER BY num_attr_keys DESC NULLS FIRST;
